import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { RouterWriter, WriterOptions } from "./types";
import { normalizeImportPath, toRoutePath } from "../resolver";
import type { RouteItem } from "../generator";

function formatMeta(meta: Record<string, unknown>, indent = 4): string {
    const json = JSON.stringify(meta, null, 2);
    const unquotedKeys = json.replace(/"([a-zA-Z_$][a-zA-Z0-9_$]*)":/g, "$1:");
    const pad = " ".repeat(indent);
    return unquotedKeys
        .split("\n")
        .map((line, idx) => (idx === 0 ? line : `${pad}${line}`))
        .join("\n");
}

export function reactRouterWriter(): RouterWriter {
    return {
        write(routes: RouteItem[], options: WriterOptions) {
            const { outputDir, fileName, importBase, pagesDir } = options;

            mkdirSync(outputDir, { recursive: true });

            // 1. Collect unique middleware components
            const middlewareMap = new Map<string, string>();
            let midCounter = 0;
            for (const r of routes) {
                if (r.middlewareComponent && !middlewareMap.has(r.middlewareComponent)) {
                    middlewareMap.set(r.middlewareComponent, `MiddlewareComponent_${midCounter++}`);
                }
            }

            // 2. Generate component declarations
            const routeDeclarations = routes.map((r, idx) =>
                `const RouteComponent_${idx} = lazy(() => import(/* @vite-ignore */ "${importBase}/${normalizeImportPath(r.file)}"));`
            );

            const middlewareDeclarations = Array.from(middlewareMap.entries()).map(([file, varName]) =>
                `const ${varName} = lazy(() => import(/* @vite-ignore */ "${importBase}/${normalizeImportPath(file)}"));`
            );

            // 3. Generate routerConfig array entries
            const generateRouteBlock = (r: RouteItem, idx: number) => {
                const pathVal = r.path || toRoutePath(r.file, pagesDir);
                const lines = [
                    `  {`,
                    `    path: "${pathVal}",`,
                    `    component: RouteComponent_${idx},`
                ];

                if (r.meta && Object.keys(r.meta).length > 0) {
                    lines.push(`    meta: ${formatMeta(r.meta, 4)},`);
                }

                lines.push(`  }`);
                return lines.join("\n");
            };

            // 4. Generate JSX Route elements (grouped by middleware component if present)
            const groupedRoutes = new Map<string, Array<{ route: RouteItem; index: number }>>();
            const topLevelRoutes: Array<{ route: RouteItem; index: number }> = [];

            routes.forEach((r, index) => {
                if (r.middlewareComponent && middlewareMap.has(r.middlewareComponent)) {
                    const key = r.middlewareComponent;
                    if (!groupedRoutes.has(key)) {
                        groupedRoutes.set(key, []);
                    }
                    groupedRoutes.get(key)!.push({ route: r, index });
                } else {
                    topLevelRoutes.push({ route: r, index });
                }
            });

            const renderElementCall = (r: RouteItem, idx: number) => {
                const pathVal = r.path || toRoutePath(r.file, pagesDir);
                const metaArg = r.meta && Object.keys(r.meta).length > 0 ? formatMeta(r.meta, 12) : "undefined";
                return `renderRouteElement(RouteComponent_${idx}, ${metaArg}, "${pathVal}", props)`;
            };

            const jsxElements: string[] = [];

            // Add top-level routes
            topLevelRoutes.forEach(({ route, index }) => {
                const pathVal = route.path || toRoutePath(route.file, pagesDir);
                jsxElements.push(
                    `      <Route key="${pathVal}" path="${pathVal}" element={${renderElementCall(route, index)}} />`
                );
            });

            // Add middleware-wrapped routes
            groupedRoutes.forEach((group, middlewareFile) => {
                const varName = middlewareMap.get(middlewareFile)!;
                jsxElements.push(`      <Route element={<${varName} />}>`);
                group.forEach(({ route, index }) => {
                    const pathVal = route.path || toRoutePath(route.file, pagesDir);
                    jsxElements.push(
                        `        <Route key="${pathVal}" path="${pathVal}" element={${renderElementCall(route, index)}} />`
                    );
                });
                jsxElements.push(`      </Route>`);
            });

            // 5. Assemble file content
            const content = [
                "// This file is auto-generated by @zarr20/rakit-routes",
                "// Do not edit this file manually",
                "",
                'import { lazy, type ComponentType, type ReactNode } from "react";',
                'import { Route } from "react-router-dom";',
                'import { RouteGuard, type AuthState } from "@zarr20/rakit-routes/client";',
                "",
                "// Route Components",
                routeDeclarations.join("\n"),
                "",
                ...(middlewareDeclarations.length > 0
                    ? ["// Middleware Layout Components", middlewareDeclarations.join("\n"), ""]
                    : []),
                "export interface GeneratedRoutesProps {",
                "  auth?: AuthState;",
                "  wrapper?: ComponentType<{",
                "    component: ComponentType<any>;",
                "    meta?: Record<string, unknown>;",
                "    path: string;",
                "  }>;",
                "}",
                "",
                "function renderRouteElement(",
                "  Component: ComponentType<any>,",
                "  meta?: Record<string, unknown>,",
                "  path?: string,",
                "  props?: GeneratedRoutesProps",
                "): ReactNode {",
                "  if (props?.wrapper) {",
                "    const Wrapper = props.wrapper;",
                '    return <Wrapper component={Component} meta={meta} path={path || ""} />;',
                "  }",
                "  if (props?.auth && meta) {",
                "    return (",
                "      <RouteGuard meta={meta} auth={props.auth}>",
                "        <Component />",
                "      </RouteGuard>",
                "    );",
                "  }",
                "  return <Component />;",
                "}",
                "",
                "export function generatedRoutes(props?: GeneratedRoutesProps): ReactNode {",
                "  return (",
                "    <>",
                jsxElements.join("\n"),
                "    </>",
                "  );",
                "}",
                "",
                "export function GeneratedRoutes(props: GeneratedRoutesProps = {}): ReactNode {",
                "  return generatedRoutes(props);",
                "}",
                "",
                "const router = [",
                routes.map(generateRouteBlock).join(",\n"),
                "];",
                "",
                "export { router, router as routes, router as routerConfig };",
                "export default router;",
                ""
            ].join("\n");

            const filePath = join(outputDir, `${fileName}.tsx`);

            writeFileSync(filePath, content, { encoding: "utf-8" });

            console.log(`✔ Router file generated at: ${filePath}`);
        }
    };
}
