import { basename, extname } from "node:path";
import { existsSync, readFileSync } from "node:fs";

const SPECIAL_BASE_NAMES = new Set([
    "middleware",
    "_middleware",
    "layout",
    "_layout",
    "meta",
    "_meta"
]);

/**
 * Returns true if the file is a configuration/special file (e.g. middleware, layout, meta)
 * that should not be exposed as a public route URL.
 */
export function isSpecialRouteFile(filePath: string): boolean {
    const base = basename(filePath).replace(/\.[^/.]+$/, "");
    return SPECIAL_BASE_NAMES.has(base);
}

export function isMiddlewareFile(filePath: string): boolean {
    const base = basename(filePath).replace(/\.[^/.]+$/, "");
    return base === "middleware" || base === "_middleware";
}

export function isLayoutFile(filePath: string): boolean {
    const base = basename(filePath).replace(/\.[^/.]+$/, "");
    return base === "layout" || base === "_layout";
}

export function isMetaFile(filePath: string): boolean {
    const base = basename(filePath).replace(/\.[^/.]+$/, "");
    return base === "meta" || base === "_meta";
}

/**
 * Checks whether a file is a React Component (e.g. renders JSX, exports a function component, or has .tsx/.jsx extension)
 */
export function isComponentFile(filePath: string): boolean {
    if (!existsSync(filePath)) return false;
    const ext = extname(filePath);
    if (ext === ".tsx" || ext === ".jsx") return true;
    if (ext === ".json") return false;
    try {
        const content = readFileSync(filePath, "utf-8");
        return (
            /<[A-Za-z0-9_]+[\s\S]*?>/.test(content) ||
            /export\s+default\s+(?:function|\([^)]*\)\s*=>|[A-Z])/.test(content)
        );
    } catch {
        return false;
    }
}
