import { resolve } from "node:path";
import { routerMapper } from "../mapper";
import { VitePluginOptions } from "./types";

/**
 * Vite plugin for @zarr20/rakit-routes.
 * Automatically generates routes on server start and reloads when files in pages are added or removed.
 */
export function rakitRoutesPlugin(options: VitePluginOptions = {}) {
    const pagesDir = options.pages?.dir ?? options.pagesDir ?? "src/pages";
    const outputDir = options.output?.dir ?? options.outputDir ?? "src/shared/router";
    const fileName = options.output?.fileName ?? options.fileName ?? "router";

    function runGenerate() {
        routerMapper({
            pages: {
                dir: pagesDir,
                extensions: options.pages?.extensions ?? [".tsx", ".ts", ".jsx", ".js"]
            },
            output: {
                dir: outputDir,
                fileName
            },
            writer: options.writer,
            importBase: options.importBase
        });
    }

    return {
        name: "@zarr20/rakit-routes",
        buildStart() {
            runGenerate();
        },
        configureServer(server: any) {
            const pagesPath = resolve(process.cwd(), pagesDir);
            server.watcher.on("add", (file: string) => {
                if (file.startsWith(pagesPath)) {
                    runGenerate();
                }
            });
            server.watcher.on("unlink", (file: string) => {
                if (file.startsWith(pagesPath)) {
                    runGenerate();
                }
            });
        }
    };
}
