import { scanPages } from "../scanner";
import { generateRouter } from "../generator";
import { reactRouterWriter } from "../writers";
import { RouterMapperConfig } from "./types";
import { computeRelativeImport } from "./relativeImport";

/**
 * Main orchestrator: scans pages, generates resolved & sorted routes, and writes router output.
 */
export function routerMapper(config: RouterMapperConfig): void {
    const files = scanPages(
        config.pages.dir,
        config.pages.extensions ?? [".tsx", ".ts", ".jsx", ".js"]
    );

    const routes = generateRouter(files, config.pages.dir);
    const writer = config.writer ?? reactRouterWriter();
    const importBase = config.importBase ?? computeRelativeImport(config.output.dir, config.pages.dir);

    writer.write(routes, {
        outputDir: config.output.dir,
        fileName: config.output.fileName ?? "router",
        importBase,
        pagesDir: config.pages.dir
    });
}
